INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021113', 'AN1923', 'エレン・イェーガー', '所属：調査兵団第104期訓練兵。   エレンは、ウォール・マリア南部のシガンシナ地区で、カーラとグリシャ・イェーガーの間に生まれた。彼は両親と、幼い頃にイェーガー家に引き取られた義理の妹ミカサと共に、この町で育った。 エレンは、ミカサや、二人が共通の親友であるアルミン・アルレルトと過ごす時間がほとんどで、二人はよく近所のいじめっ子からアルミンを守っていた。    エレンは情熱的で、意志が強く、頑固で、衝動的な若者である。彼らが子供の頃', 15, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b40882-dsj7IP943WFF.jpg', '3月30日', NULL, '梶裕貴', 170, 40882, 'MAIN', 34548) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021114', 'AN1923', 'ジーク', 'ジークは現在、獣の巨人の継承者であり、ライナー・ブラウンからは「最強の戦士」と見なされている。これは、リヴァイの「人類最強の兵士」という称号とは対照的である。', 25, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b125661-FiqFvAtNlL0v.png', '8月1日', NULL, '子安武人', 183, 125661, 'MAIN', 3712) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021115', 'AN1923', 'ミカサ・アッカーマン', '所属：第104訓練兵団、調査兵団 家族：実母（故人）、実父（故人）、グリシャ・イェーガー（養父）、カーラ・イェーガー（養母、故人）、エレン・イェーガー （養兄弟） ミカサはエレン・イェーガーの養妹であり、アルミン・アルレルトの幼なじみでもあり、ウォール・マリア南部のシガンシナ地区で二人と暮らしている。   幼い頃、両親は人身売買業者に殺害され、彼女自身も誘拐された。エレンはこの事実を突き止め、', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b40881-F3gr1PkreDvj.png', '2月10日', NULL, '石川由依', 170, 40881, 'MAIN', 28482) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021116', 'AN1923', 'アルミン・アルレルト', '所属：調査兵団第104期生 親族：祖父　アルミンは、城壁内のシガンシナ地区で生まれ育った少年で、エレン・イェーガーやミカサ・アッカーマンとは幼なじみである。 壁マリアが破られた後、彼はミカサやエレンと共に軍に入隊することを選んだ。それは、世界に偉大で有意義な影響を与えようという想いと、外の世界を見るという夢を叶えるためでもあった。幼い頃から、生まれつき好奇心旺盛なアルミンは常に', 15, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b46494-g7xYYuBtYPnO.png', '11月3日', NULL, '井上麻里奈', 163, 46494, 'MAIN', 16020) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021117', 'AN1923', 'ファルコ・グライス', '役職：戦士候補生　ファルコ・グライス は、マーレイ政府に所属するエルディア人の戦士候補生であり、コルト・グライスの弟である。ファルコは、同じく戦士候補生であるウド、ゾフィア、ガビと親しい友人関係にある。  仲間の兵士たちほど体力には恵まれていないが、その欠点を機転の利いた対応と臨機応変な判断力で補っている。彼は非常に慈悲深く思いやりのある人物で、敵の兵士であっても、人々の命を守るために惜しみなく尽力する。また、非常に礼儀正しく、', 12, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b125660-mrmpOJLjJIkv.jpg', '2月10日', NULL, '花江夏樹', 140, 125660, 'MAIN', 1301) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021118', 'AN1923', 'ガビ・ブラウン', 'ガビ・ブラウンは、リベリオ収容区に住むエルディア人で、ライナー・ブラウンのいとこである。彼女は、同じく戦士候補生であるウド、ゾフィア、ファルコ・グライスと親しい間柄だ。   ガビは非常に情熱的で頑固な性格で、感情や意見を遠慮なく表現する。また、勇敢で揺るぎない決意を持ち、自分にとってより偉大だと信じる神のために、目標を達成するためなら命を賭けることも厭わない。しかし、こうした性格ゆえに、時に横暴で独断的になることもある。T', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b125659-O37MZQWibV7g.png', '4月14日', NULL, '佐倉綾音', 138, 125659, 'MAIN', 9796) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021119', 'AN1923', 'ライナー・ブラウン', '調査兵団の隊員であり、第104期訓練兵の出身。 ライナーは、情熱的で意志が強く、強い責任感を持つ青年である。卒業時には訓練課程で2位の成績を収め、ミカサに次ぐ成績だった。仲間たちからは厚い信頼を寄せられており、第104期訓練兵たちの「兄貴分」と称されている。', 17, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b46484-P6A2GjNQn49F.png', '8月1日', NULL, '細谷佳正', 185, 46484, 'MAIN', 8255) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021120', 'AN1923', 'ベルトルト・フーバー', '所属：調査兵団　調査兵団の隊員であり、第104期訓練兵団の元訓練生。ベルトルトは卒業時、訓練生クラスで3位の成績を収め、ミカサと故郷の友人ライナーに次ぐ順位だった。彼は物静かな青年で、自分自身のことを「意志が弱く、世間の風潮に流されやすい」と評している。 クラスで3位の成績を収めたにもかかわらず、訓練指揮官は彼を「大きな可能性を秘めているが、自発性が全く欠けている」と評価していた。ベルトルトはもともと、', 16, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b46488-wm6HvkdkHoZu.jpg', '12月30日', NULL, '橋詰知久', 192, 46488, 'SUPPORTING', 904) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021121', 'AN1923', 'イェレナ', 'イェレナは、ジーク・イェーガーの指揮下で活動する「反マーレイ義勇軍」のリーダーである。彼女は、マーレイによるパラディス島への攻撃作戦が失敗に終わった後、同島へ向かった最初の調査艦隊に乗船していたマーレイ兵の一人だった。 彼女は非常に背の高い女性で、金髪の髪はストレートな前髪のあるショートボブに整えられている。大きな黒い瞳を持ち、体格やスタイルのせいでやや中性的な顔立ちをしている。イェレナはジーク・イェーガーの熱烈な信奉者であり、彼に対して深い敬意と尊敬を抱いている。普段は冷静で、', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b133216-HKl61n4F7eYv.png', NULL, NULL, '斎賀みつき', NULL, 133216, 'SUPPORTING', 1089) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021122', 'AN1923', 'キース・シャーディス', 'キース・シャーディスは、第104期訓練兵隊の主任教官だった。彼は、エレンがグリシャ医師の息子であることを知っており、エレンの努力を称賛していたことから、グリシャ医師と友人関係にあるか、何らかの関係があったようだ。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/n84305-15nngV5nTUp6.png', '8月18日', NULL, '最上嗣生', NULL, 84305, 'SUPPORTING', 277) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021123', 'AN1923', 'ナンビア ', 'は、ある外国の大使であり、ヴィリー・タイバーの幼なじみである。彼女は、マーリー・中東戦争後のリベリオ祭において、自国を代表する数人の大使の一人として活動している。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b202797-H0fiJVmfkAFI.png', NULL, NULL, '森谷彩子', NULL, 202797, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021124', 'AN1923', 'ロボフ', 'リベリオ襲撃作戦に参加した、スコットランド連隊の新兵であり、かつて駐屯地の指揮官を務めていた人物。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b209872-Q1oywyIDj05n.png', NULL, NULL, '貴弘藤原', NULL, 209872, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021125', 'AN1923', 'グリーズ', 'かつてマーリー海軍に所属していた元マーリー軍兵士で、パラディス島作戦の失敗後にパラディス島へ派遣された調査艦隊の一員である。島で捕虜となった後、ウォールズ内のレストランでウェイターとして働き始める。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b210461-4STCAkxOLvA9.png', NULL, NULL, '宮本淳', NULL, 210461, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021126', 'AN1923', 'ピーク・フィンガー', 'ピエックは、マーレーの戦士の一人として活動するエルディア人である。彼女はどこか優しく気さくな性格で、仲間の戦士や戦士候補生たちを常に気遣っている様子がうかがえる。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b125603-Z2rgiHUGbAmY.png', '8月5日', NULL, '沼倉愛美', 155, 125603, 'SUPPORTING', 3660) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021127', 'AN1923', 'リサ・ブラウス', 'サシャ・ブラウスの母親であり、ブロース氏の妻。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b134952-DKs88MOSsIzE.png', NULL, NULL, '岩男潤子', NULL, 134952, 'SUPPORTING', 14) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021128', 'AN1923', 'ハンジ・ゾエ', '所属：調査兵団；分隊長、小隊長。調査兵団第4小隊の隊長であるハンゲは、巨人の研究も担当しており、その知識を追求するあまり、巨人に執着するほどになっている。 当初は巨人を深く憎んでいたハンジだったが、巨人への憎しみを捨て、被験者に思いやりを持って接するという、従来の枠にとらわれない新たな研究手法を採用することにした。  ハンジ', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b71121-7R7CnQd3lHgt.png', '9月5日', NULL, '朴璐美', 170, 71121, 'SUPPORTING', 15322) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021129', 'AN1923', 'ケニー・アッカーマン', '所属：憲兵隊；対人統制班長。親族：クーチェル・アッカーマン（姉）、名前のない祖父。   ケニー・アッカーマンは、憲兵旅団第1内務班および対人統制班の隊員である。 しかし、数十年前、ケニーは首都で被害者を付け狙った悪名高い連続殺人犯として知られていた。   その暗い仕事内容とは裏腹に、ケニーはむしろ陽気な性格で、戦闘中に敵を挑発することを楽しんでいるようだ。戦闘の際には', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/127443-aVMXGOchpsvj.png', '2月4日', NULL, '山路和弘', NULL, 127443, 'SUPPORTING', 716) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021130', 'AN1923', 'フレーゲル・リーブス ', 'フレゲル・リーブスは、ディモ・リーブスの息子である。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/n127569-75UhiY7kpILW.jpg', NULL, NULL, '畠中祐', NULL, 127569, 'SUPPORTING', 16) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021131', 'AN1923', 'ローグ', '軍警察連隊の高位将校。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b210462-XYnFRAnXLAmK.png', NULL, NULL, '大久保利洋', NULL, 210462, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021132', 'AN1923', 'クリスタ・レンズ', '所属：調査兵団 第104期訓練生隊　訓練生クラスで10位の成績を収めたクリスタは、とても内気で優しく思いやりのある人物であり、仲間たちからは「女神」や「天使」とよく称されている。ユミルとは親友同士である。', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b62481-ZZDa7vn17lMU.png', '1月15日', NULL, '三上枝織', 145, 62481, 'SUPPORTING', 4173) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021133', 'AN1923', 'ライナー父', 'エルディア人の女性、カリナ・ブラウンと不義の関係を持っていたマーレー人男性。ライナー・ブラウンの実の父親だが、現在は疎遠になっている。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b203936-fKQtH4KkaK0F.png', NULL, NULL, '楠見尚己', NULL, 203936, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021134', 'AN1923', 'アニの父', 'アニ・レオンハートの父親であり、トレーナーでもある。彼は主に蹴りと、攻撃者の体重を逆手に取る技を用いて、アニーに容赦なく戦闘訓練を施した。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b131257-EywhPQF0aqVU.png', NULL, NULL, '石井康嗣', NULL, 131257, 'SUPPORTING', 10) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021135', 'AN1923', 'ピュレ', '新人記者であるピュレは、上司のロイのようにまだ世間に幻滅してはいません。彼は取材において非常に大胆で、通常なら「タブー」と見なされるような質問でも、憲兵隊員に臆することなく投げかけます。 彼は真実を伝えるという仕事を非常に真剣に受け止めており、政府にとってスキャンダルとなるようなニュースの掲載を阻まれると、苛立ちを隠せない。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/n130637-MHrUGfiFvMKZ.png', '2月28日', NULL, '高橋研二', NULL, 130637, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021136', 'AN1923', 'バリス', 'バリスは、リベリオ襲撃作戦に参加したスコット連隊の兵士である。 バリスはスコット連隊において非常に忠実で信頼されている隊員であり、リヴァイ・アッカーマンと共にジーク・イェーガーを護衛する任務を任された数少ない隊員の一人である。他の兵士たちがイェーガー派に寝返った後も、彼は上官への忠誠を貫き続けた。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b212204-R6jqQnVu0H5G.png', NULL, NULL, '田邊幸輔', NULL, 212204, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021137', 'AN1923', 'リヴァイ', '調査兵団内の特殊作戦班（通称「リヴァイ班」）の班長。人類最強の兵士として知られている。リヴァイは物腰が荒く、口調も率直で、規律と秩序を重んじる。潔癖症であり、自分自身、装備、そして周囲の環境に対して、一点の汚れもないほどの清潔さを求める。 兵士になる前の生活で、地下犯罪に関与していたという噂がある。感情を表に出さず、人当たりも悪いが、リヴァイは自分の分隊を深く気遣い、大いに', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b45627-CR68RyZmddGG.png', '12月25日', 'A', '神谷浩史', 160, 45627, 'SUPPORTING', 42827) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021138', 'AN1923', 'アニ・レオンハート', '士官候補生団の第104南部師団に所属していた。第104師団を卒業後、トップ10のうち4位という成績を収め、最終的に憲兵隊に入隊した。 ルームメイトはヒッチ・ドリス。無表情な少女であるアニーは、めったに笑ったり人付き合いをしたりせず、感情の表れない表情を浮かべることが多いため、孤立した一匹狼タイプと見なされている。無気力で眠たげな性格で、無意味な規律や活動に努力を注ぐ意欲はほとんどない。それにもかかわらず、アニーを突き動かすものは……', 16, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b46490-tan274Ifc1Jf.jpg', '3月22日', NULL, '嶋村侑', 153, 46490, 'SUPPORTING', 5392) ON CONFLICT DO NOTHING;
