INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021141', 'AN1923', 'コスロ', '彼は、マーリーが勝利を収める前に、中東連合軍との戦争で戦ったマーリー軍の将校である。（出典：進撃の巨人ウィキ）', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b199549-ispr2ccdtGOw.png', NULL, NULL, '奈良徹', NULL, 199549, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
