INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021143', 'AN1923', 'ドット・ピクシス', '南部地域の最高位行政官。駐屯軍の南部領土を統括するピクシスは、鋭い洞察力を持つ狡猾な指導者である。しかし、彼はアルコール依存症でもあり、側近のアンカに常に監視されている。アンカは、重要な局面で彼が寝たり酒を飲んだりするたびに、絶えず叱責している。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b62485-I0U5Cat3z65K.png', NULL, NULL, '田中正彦', NULL, 62485, 'SUPPORTING', 701) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021144', 'AN1923', 'ヒッチ・ドリス', '所属：第104士官候補生隊。  ストーヘス地区に駐屯する憲兵隊の新兵。アニ・レオンハートと同室だった。ヒッチは時折子供っぽい振る舞いを見せるが、皮肉屋で気さくな性格であり、特にマーロ・フロイデンベルクをはじめとする同僚将校たちをからかったり、いじったりすることを悪戯っぽく楽しんでいるようだ。 彼女は、上級将校たちが信じられないほど腐敗していることは周知の事実であり、その体制を自分自身の利益に利用したかったため、怠惰から憲兵隊に入隊したと主張している。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b86017-m6vXFRKWMwUo.jpg', '5月10日', NULL, '渡辺明乃', 168, 86017, 'SUPPORTING', 622) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021145', 'AN1923', 'サシャ・ブラウス', '身長：168cm　所属：第104訓練隊、調査兵団　兵士　親族：アルトゥル・ブラウス（父）、リサ・ブラウス （母）　ウォール・ローズ南部の山岳森林地帯にある、人里離れた狩猟民の村ドーパー出身のサーシャは、第104期訓練兵団の士官候補生として入隊し、卒業時には9位の成績を収めた。 卒業後、彼女はスカウト連隊への配属を選んだ。  サーシャは親しみやすく、陽気な性格の少女だ。彼女はウィットに富んだ話し方をし', 16, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b45887-QPtJH0KwqthW.jpg', '7月26日', NULL, '小林ゆう', 168, 45887, 'SUPPORTING', 9200) ON CONFLICT DO NOTHING;
