INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021150', 'AN1923', 'オニャンコポン', 'オニャンコポンは反マーリー派義勇兵の一人で、リベリオ襲撃の際には調査兵団を支援した。彼はハンジの命令に従い、調査兵団が撤退の際に使用する飛行船を操縦した。（出典：Attack on Titan Fandom）', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b192909-81EoCndP0uEH.png', NULL, NULL, '樋渡宏嗣', NULL, 192909, 'SUPPORTING', 233) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021151', 'AN1923', 'ダリス・ザックレー', '陸軍の3つの師団すべてを統括する指揮官。     __ _注：___ 「ダリス・ザックレー」は講談社による公式の英語訳である。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b71125-XXymqijVoYzV.png', NULL, NULL, '手塚秀彰', NULL, 71125, 'SUPPORTING', 44) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021152', 'AN1923', 'ロイ', 'ベテランのジャーナリストとして、ロイは反抗すれば報復を受けることを恐れ、君主制の抑圧的な性質を受け入れ、それに順応するようになった。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/n130636-vO0Kv5crIyeD.png', NULL, NULL, '小野塚貴志', NULL, 130636, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
