INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021154', 'AN1923', 'コニー・スプリンガー', '家族：母、マーティン・スプリンガー（兄）、サニー・スプリンガー（姉）  コニー・スプリンガーは第104期調査兵団の卒業生で、同期中8位の成績を収めた。ODMギアを駆使した動きの速さでは屈指とされ、鋭い旋回をこなすのが得意だ。 彼はウォール・ローズ内にある田舎のラガコ村の出身で、家族や村の人々に誇りに思ってもらうことが最大の夢である。卒業後、彼は調査兵団への入隊を選んだ。   陽気で純真なコニーは、やや集中力に欠ける面があり、', 15, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/n46486-izhPjzut6WCZ.png', '5月2日', NULL, '下野紘', 158, 46486, 'SUPPORTING', 2797) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021155', 'AN1923', 'フロック・フォルスター', 'フロックは調査兵団の新入隊員である。彼は、オルヴド地区での襲撃からシガンシナ地区への帰還までの2か月の間に、調査兵団に入隊した。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b127703-qNIccR0yPZKu.png', NULL, NULL, '小野賢章', NULL, 127703, 'SUPPORTING', 801) ON CONFLICT DO NOTHING;
