INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021158', 'AN1923', 'キヨミ・アズマビト', 'キヨミはヒズルの大使であり、パラディス島におけるエルディア人の味方である。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b202799-WlK66SqrhzED.png', NULL, NULL, '吉沢希梨', NULL, 202799, 'SUPPORTING', 9) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021159', 'AN1923', 'アルトゥル・ブラウス', '家族：リサ・ブラウス（妻）、サーシャ・ブラウス（娘）。アルトゥル・ブラウスはサーシャ・ブラウスの父親であり、ドーパー村の狩人である。サーシャが家を離れて軍に入隊するきっかけとなったのは、彼の言葉だった。  アルトゥルは、一族に深く献身する、成熟した父親のような人物であるようだ。彼は自身の生き方を大切にしている一方で、多くの人々が巨人に家を奪われたこと、そして大いなる神のために森を分かち合わなければならないことを理解している。彼は非常に賢明で、変化を受け入れる姿勢を見せ、', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b131281-TDm3VmnXgseC.png', NULL, NULL, 'かわのをとや', NULL, 131281, 'SUPPORTING', 40) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021160', 'AN1923', 'ダイナ・フリッツ', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b133215-ifxjiTHsEGNl.png', NULL, NULL, '岸本希', NULL, 133215, 'SUPPORTING', 17) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021161', 'AN1923', 'ジャン・キルシュタイン', '親族：母親のジーン・キルシュタインは第104期士官候補生隊の卒業生であり、ODM装備の操作技術と、より戦術的な視点で物事を見極める能力により、同期生の中で6位の成績を収めた。 ジーンはウォール・ローズのトロスト地区出身で、憲兵として城壁内で平穏な生活を送ることを望んで軍に入隊した。しかし、後に親友であるマルコ・ボットの言葉に説得され、またその光景を目の当たりにしたことをきっかけに、調査兵団に加わることになる。', 16, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b46498-ritqAj9FW6jX.png', '4月7日', NULL, '谷山紀章', 175, 46498, 'SUPPORTING', 7258) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021162', 'AN1923', 'ポルコガリアード', '役職：マーリーの戦士　ポルコ・ガリアードはエルディアンであり、マルセル・ガリアードの弟である。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b125662-an9dgh4LZ016.png', '11月11日', NULL, '増田俊樹', 175, 125662, 'SUPPORTING', 498) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021163', 'AN1923', 'テオ・マガト', 'マーリー軍エルディア部隊の指揮官。 かつては第1期戦士候補生の訓練における主任監督官の一人であり、その後、中東連合軍との「マーレイ・中東戦争」においてエルディア戦士たちを率い、マーレイの勝利に重要な役割を果たした。     （出典：進撃の巨人 Wiki）', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b131763-YNYd9scK4Den.jpg', NULL, NULL, '斉藤次郎', NULL, 131763, 'SUPPORTING', 81) ON CONFLICT DO NOTHING;
