INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021165', 'AN1923', 'オグウェノ', 'オグウェノは異国の大使であり、ヴィリー・タイバーの友人でもある。彼は、マーリー・ミッドイースト戦争後のリベリオ祭において、自国を代表する数人の大使の一人として務めている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b202798-Qbmf0QU02jks.png', NULL, NULL, '田邊幸輔', NULL, 202798, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021166', 'AN1923', 'ルイーゼ', '巨人の襲来時、母親と共にトロストで脱出を試みていた少女。ミカサ・アッカーマンや第104期生たちに救われた後、彼らの英雄的な行動に感化され、後に憧れのミカサに近づきたいという思いから、自ら調査兵団の新兵として入隊する。  ルイーゼは、この世で最も重要な資質は「強さ」であると信じており、その考え方は「力こそが正義」という姿勢に近いほどである。この考え方の多くは、', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b209870-urk2Tf2nV0mQ.png', '4月25日', NULL, '永井真里子', NULL, 209870, 'SUPPORTING', 20) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021167', 'AN1923', 'ナイル・ドーク', '憲兵隊長。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b71123-FswK9rrdbR9h.png', '11月1日', NULL, '勝杏里', NULL, 71123, 'SUPPORTING', 39) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021168', 'AN1923', 'グリシャ・イェーガー', 'エレン・イェーガーの父であり、ミカサ・アッカーマンの保護者。ワクチンを開発して謎のウイルス性疫病から村を救ったことで、シガンシナ地区で広く尊敬を集める著名な医師である。 また、シガンシナ地区軍団内の人脈を持つほか、シガンシナの住民や周辺のいくつかの町に対して、往診サービスも行っている。妻はカーラ・イェーガーである。', 39, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b62477-3AHBGul9bXK8.jpg', '1月26日', NULL, '土田大', NULL, 62477, 'SUPPORTING', 631) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021169', 'AN1923', 'ニコロ', 'ニコロは、かつてマーレー海軍に所属していた元マーレー兵士であり、パラディス島作戦の失敗後、パラディス島へ向かった最初の調査艦隊の一員だった。捕虜となった後、彼は島で軍用の料理人として働き始める。  ニコロは当初、パラディス島のエルディア人を「悪魔」と呼び、彼らを恐れる、ごく典型的なマーレ人だった。エルディア人に捕らえられ、彼らの傍らで生活しなければならないことに強い嫌悪感を抱いていたが、調査兵団と多くの時間を共にするうちに', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b133218-G3SQp19jnFIJ.png', NULL, NULL, '花輪英司', NULL, 133218, 'SUPPORTING', 448) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021170', 'AN1923', 'カヤ', 'ウォール・ローゼに住む一般市民。ウォール・ローゼ侵攻の際、サシャ・ブラウスに巨人から救われ、現在はブロース家と暮らしている。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/n132738-I8jNSdoNIhZI.jpg', NULL, NULL, '浜崎奈々', NULL, 132738, 'SUPPORTING', 55) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021171', 'AN1923', 'カルロ', 'カルロはマーリー軍の兵士であり、パンツァー部隊の一員である。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b205906-42ZSOfYXGfkJ.png', NULL, NULL, '田中啓太郎', NULL, 205906, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
