INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1930', 'ワンダーエッグ・プライオリティ', '2021年冬', 'PR0046', 'TVシリーズ', 12, '『ワンダーエッグ・プライオリティ』（WONDER EGG PRIORITY）は、CloverWorks制作による日本のテレビアニメ作品。略称は「ワンエグ」。2021年1月から3月まで日本テレビほかにて放送され、特別編が同年6月29日に放送された。 野島伸司が初めてテレビアニメーション制作に参加し、原案および脚本を手掛けるオリジナルアニメ作品となる。日本テレビおよびNTTドコモの両社のコンテンツ投資', 124845) ON CONFLICT DO NOTHING;
