INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1934', '回復術士のやり直し', '2021年冬', 'PR0080', 'TVシリーズ', 12, '『回復術士のやり直し』（かいふくじゅつしのやりなおし）は、月夜涙による日本のなろう系小説。サブタイトルは『〜即死魔法とスキルコピーの超越ヒール〜』。略称は「回復術士」、「かいやり」。イラストはしおこんぶが担当している。小説投稿サイト「小説家になろう」にて2016年12月から連載されている。書籍版は角川スニーカー文庫（KADOKAWA）より2017年6月から刊行されている。「次のヒット作はこれだ！', 113425) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1935', '弱キャラ友崎くん', '2021年冬', 'PR0019', 'TVシリーズ', 12, '『弱キャラ友崎くん』（じゃくキャラともざきくん、英題：The Low Tier Character "TOMOZAKI-kun"） は、屋久ユウキによる日本のライトノベル。イラストはフライが担当している。ガガガ文庫（小学館）より2016年5月から刊行されている。 第10回小学館ライトノベル大賞ガガガ文庫部門優秀賞受賞作。「次のヒット作はこれだ！ 新作ラノベ総選挙2017」（ブックウォーカー）では2', 112443) ON CONFLICT DO NOTHING;
