INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1939', '怪物事変', '2021年冬', 'PR0004', 'TVシリーズ', 12, '『怪物事変』（けものじへん）は、藍本松による日本の漫画。『ジャンプスクエア』（集英社）において、2017年1月号から連載中。2025年12月時点で全世界の累計部数は800万部を突破している。', 114085) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1940', 'たとえばラストダンジョン前の村の少年が序盤の街で暮らすような物語', '2021年冬', 'PR0058', 'TVシリーズ', 12, '『たとえばラストダンジョン前の村の少年が序盤の街で暮らすような物語』（たとえばラストダンジョンまえのむらのしょうねんがじょばんのまちでくらすようなものがたり）は、サトウとシオによる日本のライトノベル。イラストは和狸ナオが担当。略称は『ラスダン』。GA文庫（SBクリエイティブ）より2017年2月から2022年7月まで刊行された。魔王を倒した勇者たちの子孫が暮らす村から軍人を志望して都会に出てきた主人', 112649) ON CONFLICT DO NOTHING;
