INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1944', 'はたらく細胞BLACK', '2021年冬', 'PR0058', 'TVシリーズ', 13, '『はたらく細胞BLACK』（はたらくさいぼうブラック）は、原田重光（原作）、初嘉屋一生（作画）による日本の漫画。『モーニング』（講談社）にて2018年から2021年まで連載された。清水茜による漫画『はたらく細胞』（以下「本編」と呼称）のスピンオフ作品であり、清水が監修を務める。 細胞が働く不健康・不摂生な成人男性の体内環境をブラック企業に喩えて取り上げており、全編を通してシリアスかつ殺伐とした雰囲', 117533) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1945', '裏世界ピクニック', '2021年冬', 'PR0058', 'TVシリーズ', 12, '『裏世界ピクニック』（うらせかいピクニック）は、宮澤伊織による日本の小説。イラストはshirakabaが担当している。ハヤカワ文庫JA（早川書房）より2017年2月から刊行されている。『SFが読みたい！ 2018年版』ベストSF国内篇では7位を獲得している。2021年3月時点で電子版を含めたシリーズ累計部数は50万部を突破している。 ストルガツキー兄弟の『ストーカー』（原題の邦訳『路傍のピクニック', 116287) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1946', '2.43 清陰高校男子バレー部', '2021年冬', 'PR0030', 'TVシリーズ', 12, '『2.43 清陰高校男子バレー部』（にーてんよんさん せいいんこうこうだんしバレーぶ）は、壁井ユカコによる日本の小説。イラストは山川あいじが担当している。集英社のWEB文芸サイト『RENZABURO』にて2012年6月から連載開始。2013年より単行本が発売され、2015年3月から2023年10月まで集英社文庫から文庫版が発売された。2019年11月から『RENZABURO』（現・集英社文芸ステー', 113231) ON CONFLICT DO NOTHING;
