INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1950', '怪病医ラムネ', '2021年冬', 'PR0133', 'TVシリーズ', 12, '『怪病医ラムネ』（かいびょういラムネ）は、阿呆トロによる日本の漫画作品。『月刊少年シリウス』にて2017年11月号から2018年9月号まで連載され、その後同社のウェブコミック配信サイト『マガジンポケット』に移籍して2018年12月21日より配信開始。2022年2月22日の更新を最終話とし完結。', 123779) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1951', '天地創造デザイン部', '2021年冬', 'PR0012', 'TVシリーズ', 12, '『天地創造デザイン部』（てんちそうぞうデザインぶ、英語: [Ten-De-Bu] What a Strange Animal!, Heaven''s Design Team）は、蛇蔵、鈴木ツタ（共同原作）、たら子（作画）による日本の漫画。『月刊モーニングtwo』（講談社）にて、2017年3号から連載中。万能の神から依頼を受けて動物をデザインする、天地創造社の個性豊かなデザイナーや、試作を担当する技術', 117696) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1952', 'EX-ARM エクスアーム', '2021年冬', NULL, 'TVシリーズ', 12, '『EX-ARM エクスアーム』（エクスアーム）は、漫画：古味慎也、原作：HiRockによる日本の漫画。『ミラクルジャンプ』（集英社）にプロトタイプとなる連載『EX-VITA』（エクス・ヴィータ）『D''z』（ディーズ）が掲載された後、同社の『グランドジャンプ』にて2015年6号から2018年1号まで連載され、2017年12月20日から『少年ジャンプ+』に移籍して2019年6月26日まで連載された。そ', 106503) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1953', 'IDOLY PRIDE', '2021年冬', 'PR0003', 'TVシリーズ', 12, '『IDOLY PRIDE』（アイドリープライド）は、サイバーエージェントグループ、ミュージックレイン、ストレートエッジによる、アイドルをテーマとした日本のメディアミックス作品。略称は『アイプラ』。', 113814) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1954', 'オルタンシア・サーガ', '2021年冬', 'PR0058', 'TVシリーズ', 12, NULL, 114301) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1955', 'バック・アロウ', '2021年冬', 'PR0015', 'TVシリーズ', 24, '『バック・アロウ』（BACK ARROW）は、スタジオヴォルン制作による日本のテレビアニメ作品。2021年1月から6月までTOKYO MXほかにて連続2クールで放送された。 壁に囲まれた世界「リンガリンド」を舞台に、主人公であるバック・アロウが失った記憶を取り戻そうと壁の外を目指していくストーリーが描かれる。本作品のテーマは「信念」。', 114307) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1956', 'スケートリーディング☆スターズ', '2021年冬', 'PR0006', 'TVシリーズ', 12, '『スケートリーディング☆スターズ』（Skate-Leading Stars）は、J.C.STAFFによる日本のテレビアニメ。架空のフィギュアスケート団体競技「スケートリーディング」に打ち込む高校生たちを描くオリジナルアニメ作品である。2021年1月から3月までTOKYO MXほかにて放送された。 当初は2020年7月からの放送を予定していたが、新型コロナウイルスの影響で放送延期となった。2020年', 113585) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1957', 'WAVE!!～サーフィンやっぺ!!～ (TV)', '2021年冬', 'PR0012', 'TVシリーズ', 12, NULL, 130402) ON CONFLICT DO NOTHING;
