INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1961', '舞妓さんちのまかないさん', '2021年冬', 'PR0006', 'TVシリーズ', 12, '『舞妓さんちのまかないさん』（まいこさんちのまかないさん、Maiko-san Chi no Makanai-san）は、小山愛子による日本の漫画。『週刊少年サンデー』（小学館）にて2017年5・6合併号から2025年8号まで連載された。第65回（2019年度）小学館漫画賞少年向け部門受賞作品。2023年12月時点で累計発行部数は350万部を突破している。 京都の屋形（舞妓置屋）で賄いの仕事をする少', 117067) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1962', 'ゲキドル', '2021年冬', NULL, 'TVシリーズ', 12, '『ゲキドル』は、フッズエンタテインメントによる日本のメディアミックスプロジェクト。キャッチコピーは『この世界は舞台。人はみな役者。』（ウィリアム・シェイクスピアより）『演劇＋アニメ×アイドル』。世界都市同時消滅により池袋LOSTが起こった池袋で演劇を演じる少女などを描くSFストーリー。関谷あさみがキャラクター原案を手掛ける。 関谷による漫画『ゲキドル アライヴ』が『電撃マオウ』（KADOKAWA）', 124131) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1963', 'アイ★チュウ HALFWAY THROUGH THE IDOL', '2021年冬', 'PR0131', 'TVシリーズ', 12, NULL, 109010) ON CONFLICT DO NOTHING;
