INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1966', 'WIXOSS DIVA(A)LIVE', '2021年冬', 'PR0006', 'TVシリーズ', 12, '『WIXOSS DIVA(A)LIVE』（ウィクロス ディーヴァ アライブ）は、2021年1月9日（8日深夜）から3月27日（26日深夜）にかけて TOKYO MXほかにて放送されたJ.C.STAFF制作による日本のテレビアニメ。 タカラトミーが発売するトレーディングカードゲーム『WIXOSS』をベースとするオリジナルアニメであり、『WIXOSS』シリーズとしては約3年ぶりかつ通算5作目のアニメ作', 116944) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1967', 'アイカツプラネット！', '2021年冬', 'PR0114', 'TVシリーズ', 25, NULL, 128872) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1968', '真・中華一番! 2', '2021年冬', NULL, 'TVシリーズ', 12, NULL, 114304) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1969', '爆丸ジオガンライジング', '2021年冬', 'PR0070', 'TVシリーズ', 26, '『爆丸ジオガンライジング』（ばくがんジオガンライジング、英名：Bakugan: Geogan Rising）は、スピンマスターおよびタカラトミーより発売されている男児向け玩具・爆丸を原案としたアニメ作品。カナダのスピンマスターおよびネルバナとの共同製作となる。 前作『爆丸アーマードアライアンス』（同作の前作は『爆丸バトルプラネット』）の直接の続編となる第3期シリーズ。2021年1月24日よりカナダ', 131096) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1970', '東京リベンジャーズ', '2021年春', 'PR0058', 'TVシリーズ', 24, NULL, 120120) ON CONFLICT DO NOTHING;
