INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1972', '86－エイティシックス－', '2021年春', 'PR0001', 'TVシリーズ', 11, NULL, 116589) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1973', '不滅のあなたへ', '2021年春', 'PR0048', 'TVシリーズ', 20, '『不滅のあなたへ』（ふめつのあなたへ）は、大今良時による日本の漫画作品。『週刊少年マガジン』（講談社）にて、2016年50号から2020年1号まで第1部「前世編」が連載された。続く第2部「現世編」は2020年8号から2022年47号まで掲載され、2023年8号からは完結編となる第3部「来世編」が連載され、2025年27号をもって完結した。第43回講談社漫画賞少年部門受賞作。2025年4月時点で累計', 114535) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1974', 'イジらないで、長瀞さん', '2021年春', 'PR0066', 'TVシリーズ', 12, '『イジらないで、長瀞さん』（イジらないで、ながとろさん）は、ナナシによる日本の漫画作品。元々は2011年8月16日から2015年12月25日にかけてpixivで「長瀞さん」シリーズとして公開していた作品。2017年11月7日から2024年7月23日まで『マガジンポケット』にて連載された。2022年6月時点で電子版を含めた累計発行部数は230万部を突破している。メディアミックスとして、2021年と2', 120697) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1975', 'ひげを剃る。そして女子高生を拾う。', '2021年春', 'PR0019', 'TVシリーズ', 13, '『ひげを剃る。そして女子高生を拾う。』（ひげをそる そしてじょしこうせいをひろう）は、しめさばによる日本のライトノベル。20代のサラリーマンと、家出した女子高生が出会い、共同生活を送るさまが描かれる。略称は「ひげひろ」。「次のヒット作はこれだ！ 新作ラノベ総選挙2018」（ブックウォーカー）では4位を獲得している。 本作は「カクヨム」にて2017年より投稿が開始された。書籍版は同社の角川スニーカー', 114232) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1976', 'Vivy -Fluorite Eye’s Song-', '2021年春', 'PR0078', 'TVシリーズ', 13, NULL, 128546) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1977', 'フルーツバスケットThe Final', '2021年春', 'PR0070', 'TVシリーズ', 13, NULL, 124194) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1978', 'オッドタクシー', '2021年春', 'PR0034', 'TVシリーズ', 13, '『オッドタクシー』（ODDTAXI）は、P.I.C.SとOLMの共同制作による日本のテレビアニメ作品。2021年4月から6月までテレビ東京ほかにて放送された。', 128547) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1979', 'スライム倒して300年、知らないうちにレベルMAXになってました', '2021年春', 'PR0174', 'TVシリーズ', 12, '『スライム倒して300年、知らないうちにレベルMAXになってました』（スライムたおしてさんびゃくねん しらないうちにレベルマックスになってました）は、森田季節による日本のライトノベルおよびそれを原作とするメディアミックス作品。イラストは紅緒。略称は「スライム倒して300年」。', 112608) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1980', '異世界魔王と召喚少女の奴隷魔術Ω', '2021年春', 'PR0061', 'TVシリーズ', 10, NULL, 117448) ON CONFLICT DO NOTHING;
