INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1983', 'シャドーハウス', '2021年春', 'PR0046', 'TVシリーズ', 13, '『シャドーハウス』（SHADOWS HOUSE）は、ソウマトウによる日本の漫画。『週刊ヤングジャンプ』（集英社）にて、2018年40号より連載中。アプリ「ヤンジャン！」でカラー版が同時に配信され、韓国の「Neverbooks」シリーズではニアサイマル配信される。単行本はヤングジャンプ・コミックスより発売され、2026年1月時点の累計部数は日本国外と電子版を含めて350万部を突破している。 2025', 125038) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1984', '転生したらスライムだった件 転スラ日記', '2021年春', 'PR0037', 'TVシリーズ', 12, NULL, 116741) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1985', 'EDENS ZERO', '2021年春', 'PR0006', 'TVシリーズ', 25, '『EDENS ZERO』（エデンズ ゼロ）は、真島ヒロによる日本の漫画。『週刊少年マガジン』（講談社）において、2018年30号から2024年30号まで連載された。 真島の過去作に共通する「ボーイ・ミーツ・ガールから始まる冒険譚」だが、魔法が存在する世界を舞台にした『RAVE』や『FAIRY TAIL』とは異なり、神秘に満ちた宇宙を渡り歩く惑星冒険もの（スペースオペラ）になっている。', 119683) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1986', '幼なじみが絶対に負けないラブコメ', '2021年春', 'PR0051', 'TVシリーズ', 12, '『幼なじみが絶対に負けないラブコメ』（おさななじみがぜったいにまけないラブコメ）は、二丸修一による日本のライトノベルおよびそれを原作とするメディアミックス作品。イラスト担当はしぐれうい。電撃文庫（KADOKAWA）より2019年6月から2025年2月まで刊行された。略称は「おさまけ」。「このライトノベルがすごい!2020」において、文庫部門総合5位、新作2位を獲得した。2025年2月時点でシリーズ', 124675) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1987', '憂国のモリアーティ2クール', '2021年春', 'PR0043', 'TVシリーズ', 13, NULL, 124858) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1988', '究極進化したフルダイブRPGが現実よりもクソゲーだったら', '2021年春', 'PR0052', 'TVシリーズ', 12, '『究極進化したフルダイブRPGが現実よりもクソゲーだったら』（きゅうきょくしんかしたフルダイブアールピージーがげんじつよりもクソゲーだったら）は、土日月による日本のライトノベル。イラストはよう太が担当。MF文庫J（KADOKAWA）より2020年8月から刊行されている。略称は「フルダイブ」、「フルダイブRPG」。 また、2018年1月に同著者による同名の作品（イラスト・白井鋭利）が1巻のみノベルゼ', 126791) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1989', 'SHAMAN KING (2021)', '2021年春', 'PR0036', 'TVシリーズ', 52, NULL, 119675) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1990', '聖女の魔力は万能です', '2021年春', 'PR0100', 'TVシリーズ', 12, '『聖女の魔力は万能です』（せいじょのまりょくはばんのうです）は、橘由華によるライトノベル。2016年4月29日から小説投稿サイト「小説家になろう」にて「タチバナ」名義で連載されているオンライン小説を元に、2017年2月からカドカワBOOKS（KADOKAWA）より書籍化刊行されている。書籍版のイラストは珠梨やすゆきが担当。 メディアミックスとして、2017年7月から藤小豆によるコミカライズがウェブ', 123802) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1991', 'ゾンビランドサガ リベンジ', '2021年春', 'PR0023', 'TVシリーズ', 12, NULL, 110733) ON CONFLICT DO NOTHING;
