INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1993', 'SSSS.DYNAZENON', '2021年春', 'PR0002', 'TVシリーズ', 12, '『SSSS.DYNAZENON』（ダイナゼノン）は、TRIGGER制作による日本のテレビアニメ作品。2021年4月から6月にかけてTOKYO MXほかにて放送された。 円谷プロダクションの特撮ドラマ『電光超人グリッドマン』を原作とする完全新作アニメーション第2弾であり、2018年放送の第1弾『SSSS.GRIDMAN』と共にメディアミックスプロジェクト『GRIDMAN UNIVERSE』の中核をな', 113950) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1994', '美少年探偵団', '2021年春', 'PR0127', 'TVシリーズ', 12, NULL, 113428) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1995', 'スーパーカブ', '2021年春', 'PR0138', 'TVシリーズ', 12, NULL, 113418) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1996', 'ましろのおと', '2021年春', 'PR0005', 'TVシリーズ', 12, '『ましろのおと』は、羅川真里茂による津軽三味線を題材にした日本の漫画。『月刊少年マガジン』（講談社）にて2010年1月号に読み切りが掲載された後、同年5月号より連載化され、2022年9月号をもって完結した。作者にとって初となる少年誌での連載作品であり、また白泉社以外での連載も初である。タイトルには「ましろの音」と「ましろノート」（ノートは音符などの意）の2つの意味がある。 2012年に第36回講談', 122348) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1997', 'MARS RED', '2021年春', 'PR0040', 'TVシリーズ', 13, '『MARS RED』（マーズ レッド）は、藤沢文翁原作の舞台作品。2013年初演、2015年に再演となった音楽朗読劇である。 2019年より唐々煙による漫画が『月刊コミックガーデン』（マッグガーデン）にて連載開始となったほか、2020年にはアニメ史上初となる、朗読劇からアニメ化が発表されるなどメディアミックス展開されている。略称は「マズレ」。アニメ版の音楽は朗読劇の音楽監督である村中俊之が引き続き', 115183) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1998', 'バクテン!!', '2021年春', 'PR0072', 'TVシリーズ', 12, '『バクテン!!』は、ZEXCS制作による日本のテレビアニメ作品。2021年4月から6月までフジテレビ『ノイタミナ』枠ほかにて放送された。 東日本大震災発生から10年となる2021年に、フジテレビがアニプレックス・イオンエンターテイメントと共同で岩手県・宮城県・福島県の被災3県を舞台にしたアニメ作品を発表するプロジェクト「ずっとおうえん。プロジェクト 2011＋10…」の一環として制作される作品。宮', 125839) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1999', '灼熱カバディ', '2021年春', 'PR0070', 'TVシリーズ', 12, '『灼熱カバディ』（しゃくねつカバディ）は、武蔵野創による日本の漫画作品で、男子高校生らが部活動でカバディに打ち込む様子を描いたスポーツ漫画である。iOS・Android用漫画アプリ『マンガワン』（小学館）では2015年7月2日より連載され、2024年7月23日に完結した。また、ウェブコミック配信サイト『裏サンデー』（小学館）では1週遅れで連載され、2021年にテレビアニメ化、2022年には舞台化さ', 120859) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN2000', 'すばらしきこのせかい The Animation', '2021年春', 'PR0005', 'TVシリーズ', 12, NULL, 120376) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN2001', 'ドラゴン、家を買う。', '2021年春', 'PR0040', 'TVシリーズ', 12, '『ドラゴン、家を買う。』（ドラゴンいえをかう）は、原作：多貫カヲ、作画：絢薔子による日本の漫画。『月刊コミックガーデン』（マッグガーデン）において、2017年1月号から2023年1月号まで連載された。', 112376) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN2002', 'セブンナイツ レボリューション -英雄の継承者-', '2021年春', 'PR0068', 'TVシリーズ', 12, NULL, 129386) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN2003', 'さよなら私のクラマー', '2021年春', 'PR0058', 'TVシリーズ', 13, '『さよなら私のクラマー』（さよならわたしのクラマー）は、新川直司によるサッカー漫画。『月刊少年マガジン』（講談社）にて、2016年6月号から2021年1月号まで連載された。', 123494) ON CONFLICT DO NOTHING;
