INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN2006', 'カードファイト!! ヴァンガード overDress', '2021年春', 'PR0042', 'TVシリーズ', 12, '『カードファイト!! ヴァンガード overDress』（カードファイト ヴァンガード オーバードレス）は、ブシロードのトレーディングカードゲーム『カードファイト!! ヴァンガード』を原作としたテレビアニメ。 本項目では、本作品の続編として制作されたテレビアニメ『カードファイト!! ヴァンガード will+Dress』（カードファイト ヴァンガード ウィルドレス）および『カードファイト!! ヴァン', 121962) ON CONFLICT DO NOTHING;
