INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN2018', 'ヴァニタスの手記', '2021年夏', 'PR0022', 'TVシリーズ', 12, '『ヴァニタスの手記』（ヴァニタスのカルテ）は、望月淳による日本の漫画。『月刊ガンガンJOKER』（スクウェア・エニックス）にて2016年1月号より連載中。', 131646) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN2019', '月が導く異世界道中', '2021年夏', 'PR0091', 'TVシリーズ', 12, '『月が導く異世界道中』（つきがみちびくいせかいどうちゅう）は、あずみ圭による日本のライトノベルおよびそれを原作とするメディアミックス作品。略称は「ツキミチ」。 2012年に「小説家になろう」で発表され、同年にアルファポリス「第5回ファンタジー小説大賞」読者賞を受賞し、同社から書籍版も発行された。イラストはマツモトミツアキ。小説家になろうとアルファポリスの書籍で同時執筆していたが、2016年時の小説', 125206) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN2020', '小林さんちのメイドラゴンＳ', '2021年夏', 'PR0062', 'TVシリーズ', 12, NULL, 107717) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN2021', '現実主義勇者の王国再建記', '2021年夏', 'PR0006', 'TVシリーズ', 13, '『現実主義勇者の王国再建記』（げんじつしゅぎゆうしゃのおうこくさいけんき）は、どぜう丸による日本のライトノベル。略称は「現国」。2024年12月時で電子版を含めたシリーズ累計部数は320万部を突破している。 小説の他にも、漫画化・アニメ化など様々なメディアミックス展開が行われている。', 117612) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN2022', '精霊幻想記', '2021年夏', 'PR0070', 'TVシリーズ', 12, '『精霊幻想記』（せいれいげんそうき）は、北山結莉による日本のライトノベル。小説投稿サイト「小説家になろう」にて2014年2月12日から2020年10月20日まで連載、書籍版は2015年10月よりHJ文庫（ホビージャパン）から刊行されている。イラストは26巻まではRivが、27巻からは油布京子が担当。 旧タイトルは『こんな世界で』（2014年2月12日 - 2月20日）、『精霊幻想記 〜こんな世界で', 126546) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN2023', 'Sonny Boy', '2021年夏', 'PR0089', 'TVシリーズ', 12, '『Sonny Boy』（サニーボーイ）は、マッドハウス制作による日本のテレビアニメ作品。2021年7月から10月までTOKYO MXほかにて放送された。第25回文化庁メディア芸術祭アニメーション部門優秀賞受賞作品。', 132126) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN2024', 'カノジョも彼女', '2021年夏', 'PR0061', 'TVシリーズ', 12, '『カノジョも彼女』（カノジョもかのじょ）は、ヒロユキによる日本の漫画。『週刊少年マガジン』（講談社）において、2020年14号から2023年25号まで連載された。2023年10月時点で累計発行部数は200万部を突破している。 自身の告白を受け入れられて幼なじみのヒロインと恋人関係になった主人公が、別のヒロインに告白されて断り切れず多重交際状態となる作品。キャッチコピーは“ネオスタンダード・ラブコメ', 126192) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN2025', '探偵はもう、死んでいる。', '2021年夏', 'PR0052', 'TVシリーズ', 12, '『探偵はもう、死んでいる。』（たんていはもう、しんでいる。西: La detective está muerta）は、二語十による日本のライトノベル。略称は「たんもし」。イラストはうみぼうずが担当している。第15回MF文庫Jライトノベル新人賞《最優秀賞》を受賞。MF文庫J（KADOKAWA）より2019年11月25日から刊行されている。 2022年7月時点でシリーズ累計部数は100万部を突破してい', 128712) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN2026', 'ぼくたちのリメイク', '2021年夏', 'PR0125', 'TVシリーズ', 12, '『ぼくたちのリメイク』は、木緒なちによる日本のライトノベル。略称は「ぼくリメ」。イラストはえれっとが担当。MF文庫J（KADOKAWA）より2017年3月25日から2023年3月25日まで刊行された。 ゲームディレクターの主人公が10年前の大学生時代にタイムリープし、人生の再起をかけて奮闘する姿を描く。『このライトノベルがすごい!』2018年版では文庫部門6位、2019年版では同7位。 メディアミ', 114065) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN2027', 'うらみちお兄さん', '2021年夏', 'PR0065', 'TVシリーズ', 13, '『うらみちお兄さん』（うらみちおにいさん）は、久世岳による日本のWeb漫画作品。Pixivコミック内のウェブコミック配信サイト『comic POOL』にて2017年5月12日より連載中。架空の子供向け教育番組「ママンとトゥギャザー」に出演する、31歳の体操のお兄さん・表田裏道および番組に関わる人物の世知辛くも生々しい日常を描くブラック系ギャグ漫画。 2017年2月9日に作者の久世のTwitterに', 112802) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN2028', 'ジャヒー様はくじけない！', '2021年夏', 'PR0024', 'TVシリーズ', 20, NULL, 132456) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN2029', '死神坊ちゃんと黒メイド', '2021年夏', 'PR0006', 'TVシリーズ', 12, '『死神坊ちゃんと黒メイド』（しにがみぼっちゃんとくろメイド）は、イノウエによる日本の漫画。『サンデーうぇぶり』（小学館）にて、2017年10月3日から 2022年5月17日まで連載された。2023年時点で累計発行部数は180万部を突破している。メディアミックスとしてテレビアニメも制作され、第1期が2021年7月から9月まで、第2期が2023年7月から9月まで、第3期が2024年4月から6月まで放送', 129277) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN2030', '乙女ゲームの破滅フラグしかない悪役令嬢に転生してしまった…Ｘ', '2021年夏', 'PR0024', 'TVシリーズ', 12, NULL, 120209) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN2031', '迷宮ブラックカンパニー', '2021年夏', 'PR0024', 'TVシリーズ', 12, '『迷宮ブラックカンパニー』（めいきゅうブラックカンパニー）は、安村洋平による日本の漫画。マッグガーデンのウェブコミック配信サイト『MAGCOMI』にて2016年12月5日より連載開始。2018年4月5日からは、同社の月刊誌『月刊コミックガーデン』にて同年5月号より同誌が休刊となる2026年4月号まで並行して連載が行われた。 転移した異世界のブラック企業に勤めることになった主人公が、安定したニート生', 120608) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN2032', '出会って5秒でバトル', '2021年夏', NULL, 'TVシリーズ', 12, '『出会って5秒でバトル』（であってごびょうでバトル）は、はらわたさいぞうがウェブサイト上で発表した日本の漫画。2015年8月11日よりみやこかしわを作画に迎えたリメイク版が小学館の『裏サンデー』および『マンガワン』にて連載中。コミックスの累計発行部数は2022年7月時点で350万部を突破している。 メディアミックスとしてテレビアニメ化が決定した。', 126047) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN2033', '海賊王女', '2021年夏', 'PR0043', 'TVシリーズ', 12, '『海賊王女』（かいぞくおうじょ、英語: Fena: Pirate Princess）は、Production I.Gによる日本のテレビアニメ作品。2021年8月より北米のAdult Swim『Toonami』のアニメの放送枠にて放送およびCrunchyrollにて配信が実施された後、同年10月から12月までTOKYO MXほかにて国内放送された。 「18世紀」「王女」「侍」「海賊」をそれぞれテーマ', 122052) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN2034', '女神寮の寮母くん。', '2021年夏', 'PR0093', 'TVシリーズ', 10, '『女神寮の寮母くん。』（めがみりょうのりょうぼくん）は、日野行望による日本の漫画。『月刊少年エース』（KADOKAWA）にて、2018年2月号から2022年8月号まで連載された。', 117989) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN2035', '白い砂のアクアトープ', '2021年夏', 'PR0083', 'TVシリーズ', 24, '『白い砂のアクアトープ』（しろいすなのアクアトープ）は、P.A.WORKS制作による日本のテレビアニメ。2021年7月から12月にかけてTOKYO MXほかにて放送された。沖縄県南城市の水族館を舞台に、2人の少女の絆や葛藤、成長を描く青春群像劇。 『花咲くいろは』『SHIROBAKO』『サクラクエスト』に続く、P.A.WORKSの「お仕事シリーズ」第4弾となる。', 128545) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN2036', '平穏世代の韋駄天達', '2021年夏', 'PR0023', 'TVシリーズ', 11, '『平穏世代の韋駄天達』（へいおんせだいのいだてんたち）は、天原原作による日本の漫画。元々は天原が商業デビューする前にウェブサイト「新都社」にて発表した作品であり、2016年から更新が停止していた。しかし2018年、内容を再構成し、クール教信者を作画に迎え、『ヤングアニマル』（白泉社）にて2018年17号より2024年16号まで連載された。2021年5月27日からは、同社の漫画アプリ『マンガPark', 122434) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN2037', 'ピーチボーイリバーサイド', '2021年夏', 'PR0012', 'TVシリーズ', 12, '『ピーチボーイリバーサイド』（PEACH BOY RIVERSIDE）はクール教信者による日本の漫画作品。新都社のウェブコミック配信サイト『週刊ヤングVIP』にて連載中。', 122441) ON CONFLICT DO NOTHING;
