INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN2043', 'SCARLET NEXUS', '2021年夏', 'PR0102', 'TVシリーズ', 26, '『SCARLET NEXUS』（スカーレットネクサス）は、バンダイナムコエンターテインメントから2021年6月24日に発売されたXbox One・Xbox Series X/S・PlayStation 4・PlayStation 5・PC（Steam）用アクションRPG、テレビアニメである。通称『スカネク』。 本作は、機能が拡張された人間によってあらゆることがコントロールされる世界を舞台に、人間の', 131150) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN2044', 'かげきしょうじょ!!', '2021年夏', 'PR0027', 'TVシリーズ', 13, '『かげきしょうじょ!!』は、斉木久美子による日本の漫画作品。『かげきしょうじょ！』として『ジャンプ改』（集英社）にて2012年6月号から2014年11月号まで連載された。その後同誌の休刊に伴い、タイトルを『かげきしょうじょ!!』と改題して『MELODY』（白泉社）にて2015年4月号より連載中。2019年3月5日に集英社版を再編集した『かげきしょうじょ!! シーズンゼロ』が花とゆめコミックススペシ', 125446) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN2045', 'ラブライブ!スーパースター!!', '2021年夏', 'PR0102', 'TVシリーズ', 12, '『ラブライブ！スーパースター!!』は、KADOKAWA（アスキー・メディアワークスブランド）、ランティス（バンダイナムコミュージックライブ）、サンライズ（バンダイナムコフィルムワークス）の3者によるプロジェクト「ラブライブ!シリーズ」の第4作。', 114979) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN2046', 'マギアレコード 魔法少女まどか☆マギカ外伝 2nd SEASON -覚醒前夜-', '2021年夏', 'PR0127', 'TVシリーズ', 8, NULL, 117002) ON CONFLICT DO NOTHING;
