INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN2050', 'ゲッターロボ アーク', '2021年夏', NULL, 'TVシリーズ', 13, '『ゲッターロボ アーク』は、永井豪原作、石川賢とダイナミックプロ作画により、2001年から2003年まで双葉社アクションピザッツ増刊『スーパーロボットマガジン』で連載されていた漫画、および作品内に登場する架空のロボットの名称。 1974年から石川が執筆した「ゲッターロボサーガ」シリーズの最後の作品で、漫画版『ゲッターロボ號』の続編となっている。掲載誌の休刊により「第一部・完」として終了。単行本化の', 125640) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN2051', 'TSUKIPRO THE ANIMATION 2', '2021年夏', 'PR0140', 'TVシリーズ', 13, NULL, 125909) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN2052', 'プリティーオールフレンズセレクション', '2021年夏', 'PR0071', 'TVシリーズ', 16, '『プリティーオールフレンズセレクション』は、タカラトミーとシンソフィアが共同開発したアーケードゲーム『プリティーシリーズ』を原作とする日本のテレビアニメ。2021年6月6日から9月19日までテレビ東京系列他で放送された。 『ワッチャプリマジ!』開始に向けて過去作品を振り返るため、『プリティーリズム』シリーズ、『プリパラ』シリーズ、『キラッとプリ☆チャン』の3作品の傑作選を放送。', 136206) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN2053', '鬼滅の刃 無限列車編 (TV)', '2021年秋', 'PR0044', 'TVシリーズ', 7, NULL, 129874) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN2054', '古見さんは、コミュ症です。', '2021年秋', 'PR0034', 'TVシリーズ', 12, '『古見さんは、コミュ症です。』（こみさんはコミュしょうです）は、オダトモヒトによる日本の漫画。『週刊少年サンデー』（小学館）において、2016年25号から2025年9号まで連載された。 コミュ症（#用語参照）の女子高生と、普通の男子高校生の交流を中心に描いたコメディ作品。もともと『週刊少年サンデー』2015年42号の企画「新世代サンデーグランプリ」にて掲載された同タイトルの読切が人気を博したことか', 133965) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN2055', '無職転生 ～異世界行ったら本気だす～ 第2クール', '2021年秋', 'PR0045', 'TVシリーズ', 12, NULL, 127720) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN2056', '王様ランキング', '2021年秋', 'PR0078', 'TVシリーズ', 23, '『王様ランキング』（おうさまランキング）は、十日草輔による日本の漫画。漫画投稿サービス『マンガハック』にて、2017年5月20日から毎週土曜日に更新されている。『みんなが選ぶTSUTAYAコミック大賞2019』6位。単行本がKADOKAWAのビームコミックスレーベルより発売されており、2023年6月時点で累計発行部数は220万部を突破している。', 113717) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN2057', '世界最高の暗殺者、異世界貴族に転生する', '2021年秋', 'PR0024', 'TVシリーズ', 12, '『世界最高の暗殺者、異世界貴族に転生する』（せかいさいこうのあんさつしゃ、いせかいきぞくにてんせいする）は、月夜涙による日本のライトノベル。略称は「暗殺貴族」。小説家になろうにて2018年7月から2021年10月まで投稿され、書籍版が角川スニーカー文庫（KADOKAWA）より2019年2月から刊行されている。「次のヒット作はこれだ！ 新作ラノベ総選挙2019」文庫部門（ブックウォーカー）では4位を', 129898) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN2058', '86－エイティシックス－ 第2クール', '2021年秋', 'PR0001', 'TVシリーズ', 12, NULL, 131586) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN2059', 'takt op.Destiny', '2021年秋', 'PR0089', 'TVシリーズ', 12, NULL, 131565) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN2060', '見える子ちゃん', '2021年秋', 'PR0021', 'TVシリーズ', 12, '『見える子ちゃん』（みえるこちゃん）は、泉朝樹による漫画作品。2018年11月2日より『ComicWalker』（KADOKAWA）にて連載を開始し、2021年7月16日より『ComicWalker』内の新レーベル『WebComicアパンダ』に移籍して連載中。単行本は2019年4月22日より刊行されている。累計発行部数は2025年3月時点で330万部を突破している。 2018年、泉朝樹が本作品をT', 131083) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN2061', 'プラチナエンド', '2021年秋', 'PR0040', 'TVシリーズ', 24, '『プラチナエンド』（Platinum End）は、原作：大場つぐみ、漫画：小畑健による日本の漫画。『ジャンプスクエア』（集英社）において、2015年12月号から2021年2月号まで連載された。大場と小畑のタッグによる作品としては『DEATH NOTE』『バクマン。』に続く第3作となる。2020年12月時点で世界累計発行部数は450万部を突破している。 メディアミックスとして、テレビアニメが2021', 127401) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN2062', '真の仲間じゃないと勇者のパーティーを追い出されたので、辺境でスローライフすることにしました', '2021年秋', NULL, 'TVシリーズ', 13, '『真の仲間じゃないと勇者のパーティーを追い出されたので、辺境でスローライフすることにしました』（しんのなかまじゃないとゆうしゃのパーティーをおいだされたので へんきょうでスローライフすることにしました）は、ざっぽんによる日本のライトノベル。略称は「真の仲間」。2017年10月から小説家になろうに投稿され、2018年6月から2025年7月まで角川スニーカー文庫（KADOKAWA）より書籍が刊行された', 126213) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN2063', '先輩がうざい後輩の話', '2021年秋', 'PR0051', 'TVシリーズ', 12, '『先輩がうざい後輩の話』（せんぱいがうざいこうはいのはなし）は、しろまんたによる日本の漫画作品。作者のTwitter上で連載され、一迅社より書籍化。2018年7月6日より一迅社のWebコミック配信サイト『comic POOL』でも連載された。少しガサツだが面倒見の良い会社の先輩である武田晴海と、武田をうざいと思いつつも実はまんざらでもなかったり、しかし素直になれない後輩の五十嵐双葉の関係を描く。', 120646) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN2064', '最果てのパラディン', '2021年秋', 'PR0175', 'TVシリーズ', 12, '『最果てのパラディン』（さいはてのパラディン）は、柳野かなたによる日本のライトノベル。小説投稿サイト『小説家になろう』で2015年5月1日に連載開始。書籍化の打診を受け、2016年3月25日からオーバーラップ文庫（オーバーラップ）で刊行が始まった。書籍化後も『小説家になろう』での連載は継続している。いわゆる「転生もの」から発想を得た作品であり、前世の記憶がある少年を主人公にした異世界ファンタジーで', 132473) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN2065', '進化の実～知らないうちに勝ち組人生～', '2021年秋', NULL, 'TVシリーズ', 12, NULL, 129068) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN2066', '月とライカと吸血姫', '2021年秋', 'PR0122', 'TVシリーズ', 12, '『月とライカと吸血姫』（つきとらいかとノスフェラトゥ、Луна, Лайка и Носферату）は、牧野圭祐による日本のライトノベル。イラストはかれいが担当しており、『ガガガ文庫』（小学館）から2016年12月20日から2021年10月19日まで刊行された。 冷戦期の宇宙開発競争をモデルに、吸血種族「ノスフェラトゥ」が人類と共に月を目指す姿を描く。『このライトノベルがすごい!』では2018年', 131019) ON CONFLICT DO NOTHING;
