INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN2071', '吸血鬼すぐ死ぬ', '2021年秋', 'PR0089', 'TVシリーズ', 12, '『吸血鬼すぐ死ぬ』（きゅうけつきすぐしぬ、The Vampire dies in no time.）は、盆ノ木至による日本の漫画。『週刊少年チャンピオン』（秋田書店）において、2015年30号から連載中。2023年24号に掲載された後は盆ノ木の体調不良により休載していたが、2025年39号より同年45号まで短期集中連載として連載した後、2025年46号からしばらく休載される。略称は「吸死」。単行本', 118103) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN2072', 'ビルディバイド -#000000​(コードブラック)-', '2021年秋', 'PR0058', 'TVシリーズ', 12, NULL, 132525) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN2073', 'SELECTION PROJECT', '2021年秋', 'PR0051', 'TVシリーズ', 13, '『SELECTION PROJECT』（セレクション・プロジェクト）は、KADOKAWA×動画工房による「アイドル×オーディション×リアリティーショー」をテーマとした、日本のメディアミックスプロジェクトである。略称はセレプロ。 同じ夢を目指す戦友で、ライバルでもある少女たちの青春熱血オーディションバトルである。', 126790) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN2074', 'ヴィジュアルプリズン', '2021年秋', 'PR0001', 'TVシリーズ', 12, '『ヴィジュアルプリズン』（VISUAL PRISON）は、A-1 Pictures制作による日本のテレビアニメ作品。略称は「ヴィジュプリ」。2021年10月から12月までTOKYO MXほかにて放送された。 上松範康原作によるオリジナルアニメであり、音楽は上松が率いる音楽クリエイター集団Elements Gardenが担当する。 物語の骨心は、ヴァンパイアとなった人々が結成した音楽バンドが、一定期', 131584) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN2075', 'さんかく窓の外側は夜', '2021年秋', 'PR0059', 'TVシリーズ', 12, '『さんかく窓の外側は夜』（さんかくまどのそとがわはよる）は、ヤマシタトモコによる漫画作品。『MAGAZINE BE×BOY』（リブレ）にて、2013年4月号から2021年1月号まで連載された。2021年3月時点で累計発行部数は170万部を突破している。 霊が見える書店員と除霊師が心霊探偵コンビを組んで、除霊や連続殺人事件の謎を追うミステリー・ホラー漫画。 除霊の演出として、除霊師が魂に触れる能力を', 126897) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN2076', 'マブラヴ オルタネイティヴ', '2021年秋', 'PR0176', 'TVシリーズ', 12, '『マブラヴ オルタネイティヴ』（英: Muv-Luv Alternative）は、アダルトゲームメーカー âge（アージュ）の恋愛アドベンチャーゲーム、およびこれを原作とするメディアミックス作品群の総称である。『マブラヴ』の続編にあたる。前作UNLIMITED編の物語開始時点にタイムスリップした主人公・白銀武は、地球外起源種BETAとの戦争に人類が敗北した歴史を覆すため、未来の歴史の記憶を頼りに再', 112716) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN2077', 'Deep Insanity THE LOST CHILD', '2021年秋', 'PR0024', 'TVシリーズ', 12, NULL, 136947) ON CONFLICT DO NOTHING;
