INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN2079', '境界戦機', '2021年秋', 'PR0177', 'TVシリーズ', 13, '『境界戦機』（きょうかいせんき）は、SUNRISE BEYONDとBANDAI SPIRITSによる日本のオリジナルテレビアニメ。テレビ東京ほかにて、第一部が2021年10月から12月まで放送され、第二部は2022年4月から6月まで放送された。 2023年2月に境界戦機シリーズの最新作、『境界戦機 極鋼ノ装鬼』（きょうかいせんき きょっこうのそうき）の企画が進行中であることが発表され、同年8月から', 131005) ON CONFLICT DO NOTHING;
