INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN2083', 'テスラノート', '2021年秋', NULL, 'TVシリーズ', 13, '『テスラノート』（TESLA NOTE）は、原作を西田征史と久保忠佳、作画を三宮宏太が担当する日本の漫画。『週刊少年マガジン』（講談社）にて2021年6号より32号まで連載され、『マガジンポケット』（同）に移籍して2021年36・37合併号から2022年20号まで連載された。', 132071) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN2084', 'ルパン三世 PART6', '2021年秋', 'PR0070', 'TVシリーズ', 25, '『ルパン三世 PART6』（ルパンさんせい パートシックス）は、モンキー・パンチによる漫画作品『ルパン三世』を原作とした日本のテレビアニメシリーズの6作目。『ルパン三世』のアニメ化50周年記念作品。2021年10月10日から2022年3月27日まで、日本テレビ系列ほかにて放送された。多数の作品があるため、本項では本作を含めTVシリーズに関しては便宜上『TV第○シリーズ』と表記する。 キャッチコピー', 134623) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN2085', 'デジモンゴーストゲーム', '2021年秋', 'PR0039', 'TVシリーズ', 67, '『デジモンゴーストゲーム』（DIGIMON GHOST GAME）は、デジモンシリーズのテレビアニメ第9作で、東映アニメーションのアニメーション制作による、日本のテレビアニメ作品。2021年10月から2023年3月まで、フジテレビほかにて全68話が放送された。', 137309) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN2086', '逆転世界ノ電池少女', '2021年秋', 'PR0003', 'TVシリーズ', 12, '『逆転世界ノ電池少女』（ぎゃくてんせかいノでんちしょうじょ、RUMBLE GARANNDOLL）は、Lerche制作による日本のテレビアニメ作品。2021年10月から12月までAT-Xほかにて放送された。当初は2クールの予定だったが、予算が集まらず1クールに変更された経緯が監督により明かされている。', 131878) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN2087', 'メガトン級ムサシ', '2021年秋', 'PR0034', 'TVシリーズ', 13, '『メガトン級ムサシ』（メガトンきゅうムサシ、英：MEGATON MUSASHI）は、レベルファイブ制作によるコンピュータゲームおよび同作品に登場するロボット兵器、ならびにそれらを中心としたメディアミックスコンテンツ。ゲーム版はNintendo Switch / PlayStation 4のマルチプラットフォームで2021年11月11日に発売。当初はiOS / AndroidやPlayStation', 87502) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN2088', 'シキザクラ', '2021年秋', NULL, 'TVシリーズ', 12, 'シキザクラ（四季桜、学名：Cerasus × subhirtella ‘Semperflorens’ Miyoshi）はバラ目バラ科サクラ属のサクラ。エドヒガン系の中のコヒガン系の栽培品種で、マメザクラとエドヒガンが交雑した種間雑種で、春と秋から冬にかけての二度開花する二季咲きが最大の特徴である。', 105119) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN2089', 'ワッチャプリマジ！', '2021年秋', 'PR0162', 'TVシリーズ', 51, NULL, 136119) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN2090', 'MUTEKING THE Dancing HERO', '2021年秋', 'PR0061', 'TVシリーズ', 12, '『MUTEKING THE Dancing HERO』（ムテキング・ザ・ダンシング・ヒーロー）は、タツノコプロ原作の『とんでも戦士ムテキング』をリブートしたテレビアニメ。2021年10月から12月までテレビ大阪ほかにて放送された。 タツノコプロと手塚プロダクションが初めてタッグを組んで制作する作品でもある。主人公・ムテキ役の声優は、ホリプロインターナショナル主催の一般公募オーディションで選ばれた真', 109745) ON CONFLICT DO NOTHING;
